                }
                case RecordTypeInts.DESC:
                {
                    _DESCLocation = (stream.Position - offset);
                    return (int)MiscItem_FieldIndex.DESC;
                }
                case RecordTypeInts.AQIC:
                {
                    _AQICLocation = (stream.Position - offset);
                    return (int)MiscItem_FieldIndex.AQIC;
                }
                case RecordTypeInts.DIQO:
                {
                    _QuestLocation = (stream.Position - offset);
                    return (int)MiscItem_FieldIndex.Quest;
                }
                case RecordTypeInts.CVPA:
                {
                    _CVPALocation = (stream.Position - offset);
                    return (int)MiscItem_FieldIndex.CVPA;
                }
                case RecordTypeInts.CDIX:
                {
                    _CDIXLocation = (stream.Position - offset);
                    return (int)MiscItem_FieldIndex.CDIX;
                }
                case RecordTypeInts.DATA:
                {
                    _DataLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)MiscItem_FieldIndex.Data;
                }
                case RecordTypeInts.VMAD:
                {
                    _VMADLocation = (stream.Position - offset);
                    return (int)MiscItem_FieldIndex.VMAD;
                }
                case RecordTypeInts.HGLB:
                {
                    _HGLBLocation = (stream.Position - offset);
                    return (int)MiscItem_FieldIndex.HGLB;
                }
                case RecordTypeInts.MCQP:
                {
                    _MCQPLocation = (stream.Position - offset);
                    return (int)MiscItem_FieldIndex.MCQP;
                }
                default:
                    return base.FillRecordType(
                        stream: stream,
                        finalPos: finalPos,
                        offset: offset,
                        type: type,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        translationParams: translationParams.WithNoConverter());
            }
